mapper.select:

SELECT COALESCE(SUM(l.quantity), 0)
                    FROM warehouse_outbound_line l
                    JOIN warehouse_outbound o ON o.outbound_id = l.outbound_id
                    WHERE o.warehouse_id = #{warehouseId}
                      AND l.sku_id = #{skuId}
                      AND l.batch_no = #{batchNo}
                      AND o.status IN ('DRAFT', 'PICKED')
